return ['domain'=>NULL,'plural-forms'=>'nplurals=6; plural=(n == 0) ? 0 : ((n == 1) ? 1 : ((n == 2) ? 2 : ((n % 100 >= 3 && n % 100 <= 10) ? 3 : ((n % 100 >= 11 && n % 100 <= 99) ? 4 : 5))));','language'=>'ar','project-id-version'=>'Babilim 1.2.3','pot-creation-date'=>'2026-11-09T07:54:01+00:00','po-revision-date'=>'2026-11-09T07:54:01+00:00','x-generator'=>'Babilim','messages'=>['Sent when you press Enable Babilim, and again if the site has to register anew: your site\'s URL, the WordPress, PHP and Babilim versions, the language of your site and the languages in use on it, and a public key generated for this site.'=>'تُرسل عند الضغط على «تفعيل Babilim»، وكذلك مرة أخرى إذا اضطر الموقع إلى التسجيل من جديد: عنوان URL لموقعك، وإصدارات WordPress وPHP وBabilim، ولغة موقعك واللغات المستخدمة فيه، والمفتاح العام الذي أُنشئ لهذا الموقع.','Sent on every check: the list of installed plugins and themes with the state of any Babilim translation installed for them, the languages in use, and short diagnostic codes.'=>'تُرسل مع كل فحص: قائمة الإضافات والقوالب المثبّتة مع حالة أي ترجمة من Babilim مثبّتة لها، واللغات المستخدمة، ورموز التشخيص القصيرة.','Every request includes your site\'s URL, and the site\'s access token is included whenever the service needs it.'=>'يتضمن كل طلب عنوان URL لموقعك، ويُرسل رمز الوصول الخاص بالموقع كلما احتاجت إليه الخدمة.','What Babilim sends to the service'=>'ما الذي يرسله Babilim إلى الخدمة','Your site\'s URL'=>'عنوان URL لموقعك','WordPress version'=>'إصدار WordPress','PHP version'=>'إصدار PHP','Babilim version'=>'إصدار Babilim','Your site\'s language'=>'لغة موقعك','Languages in use on your site'=>'اللغات المستخدمة على موقعك','A public key for this site'=>'المفتاح العام لهذا الموقع','A public key generated for this site, used to prove requests genuinely come from this site. Only the public half is ever sent; the private half stays on your site.'=>'مفتاح عام أُنشئ لهذا الموقع، ويُستخدم لإثبات أن الطلبات صادرة فعلًا من هذا الموقع. لا يُرسل إلا الجزء الع